import { NextResponse, after } from 'next/server'
import { supabaseAdmin } from '@/lib/automations/admin-client'
import { runAutomationsForTrigger } from '@/lib/automations/engine'
import { findOrCreateContact } from '@/lib/api/v1/contacts'
import { checkSharedRateLimit, rateLimitResponse } from '@/lib/rate-limit'

const MAX_BODY_BYTES = 64 * 1024
const MIN_TOKEN_LENGTH = 24

/**
 * POST /api/automations/webhook/<token> — the `incoming_webhook`
 * automation trigger (respond.io parity). The token in the path is the
 * secret (generated by the builder, stored in `trigger_config.token`).
 *
 * Body: any JSON object. `phone` (E.164) selects — or creates — the
 * contact the run is for; `name` / `email` seed a new contact. Every
 * top-level scalar becomes `{{ vars.<key> }}` for the steps.
 */
export async function POST(request: Request, context: { params: Promise<{ token: string }> }) {
  const { token } = await context.params
  if (!token || token.length < MIN_TOKEN_LENGTH) {
    return NextResponse.json({ error: 'Not found' }, { status: 404 })
  }

  const limit = await checkSharedRateLimit(`automation-webhook:${token}`, { limit: 60, windowMs: 60_000 })
  if (!limit.success) return rateLimitResponse(limit)

  const text = await request.text()
  if (text.length > MAX_BODY_BYTES) {
    return NextResponse.json({ error: 'Payload too large' }, { status: 413 })
  }
  let payload: Record<string, unknown>
  try {
    const parsed = text ? JSON.parse(text) : {}
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('not an object')
    payload = parsed as Record<string, unknown>
  } catch {
    return NextResponse.json({ error: 'Body must be a JSON object' }, { status: 400 })
  }

  const db = supabaseAdmin()
  const { data: automation } = await db
    .from('automations')
    .select('id, account_id, user_id, is_active')
    .eq('trigger_type', 'incoming_webhook')
    .eq('trigger_config->>token', token)
    .maybeSingle()
  if (!automation) return NextResponse.json({ error: 'Not found' }, { status: 404 })
  if (!automation.is_active) return NextResponse.json({ error: 'Automation is not active' }, { status: 409 })

  let contactId: string | null = null
  if (typeof payload.phone === 'string' && payload.phone.trim()) {
    try {
      const contact = await findOrCreateContact(db, automation.account_id, automation.user_id, {
        phone: payload.phone,
        name: typeof payload.name === 'string' ? payload.name : null,
        email: typeof payload.email === 'string' ? payload.email : null,
      })
      contactId = contact.id
    } catch (err) {
      return NextResponse.json({ error: err instanceof Error ? err.message : 'Invalid phone' }, { status: 400 })
    }
  }

  const vars: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(payload)) {
    if (/^\w{1,64}$/.test(key) && ['string', 'number', 'boolean'].includes(typeof value)) vars[key] = value
  }

  // Runs every automation listening on this token's account+trigger whose
  // token matches; dispatch filters by trigger type, so pin it to this one.
  after(() =>
    runAutomationsForTrigger({
      accountId: automation.account_id,
      triggerType: 'incoming_webhook',
      contactId,
      context: { vars, webhook_token: token },
    }),
  )
  return NextResponse.json({ accepted: true, contact_id: contactId }, { status: 202 })
}
